def test_ch04_optimized_torchcomms_overlaps_aux_compute_before_comm_wait() -> None:
    for relative, aux_marker, output_marker in (
        (
            "optimized_torchcomms.py",
            "aux_out = aux_block.forward_prepared(inputs)",
            "reduced.add_(aux_out)",
        ),
        (
            "optimized_torchcomms_multigpu.py",
            "for _ in aux_pass_range:",
            "comm_out.add_(aux_out)",
        ),
    ):
        source = (REPO_ROOT / "ch04" / relative).read_text(encoding="utf-8")
        step_section = source.split("def _step", maxsplit=1)[1].split(
            "for _ in range(max(warmup",
            maxsplit=1,
        )[0]
        post_launch_section = step_section.split("with torch.cuda.stream(comm_stream):", maxsplit=1)[1]

        assert step_section.count("torch.cuda.current_stream()") == 1
        assert "current_stream = torch.cuda.current_stream()" in step_section
        assert "comm_stream.wait_stream(current_stream)" in step_section
        assert "current_stream.wait_stream(comm_stream)" in step_section
        assert "comm_stream.wait_stream(torch.cuda.current_stream())" not in step_section
        assert "torch.cuda.current_stream().wait_stream(comm_stream)" not in step_section
        assert post_launch_section.index(aux_marker) < post_launch_section.index(
            "current_stream.wait_stream(comm_stream)"
        )
        assert output_marker in post_launch_section
        assert "_ = reduced + aux_out" not in post_launch_section

    multigpu_source = (REPO_ROOT / "ch04" / "optimized_torchcomms_multigpu.py").read_text(encoding="utf-8")
    multigpu_benchmark = multigpu_source.split("def benchmark_fn", maxsplit=1)[1].split(
        "def capture_verification_payload",
        maxsplit=1,
    )[0]
    assert "self._aux_pass_range = range(_AUX_PASSES)" in multigpu_source
    assert "for _ in self._aux_pass_range:" in multigpu_benchmark
    assert "for _ in range(_AUX_PASSES):" not in multigpu_benchmark
    assert "aux_pass_range = range(_AUX_PASSES)" in multigpu_source
    assert "for _ in aux_pass_range:" in step_section

    baseline_multigpu_source = (
        REPO_ROOT / "ch04" / "baseline_torchcomms_multigpu.py"
    ).read_text(encoding="utf-8")
    baseline_multigpu_worker = baseline_multigpu_source.split("def _run_worker", maxsplit=1)[
        1
    ].split(
        "def main",
        maxsplit=1,
    )[0]
    baseline_multigpu_benchmark = baseline_multigpu_source.split(
        "def benchmark_fn",
        maxsplit=1,
    )[1].split(
        "def capture_verification_payload",
        maxsplit=1,
    )[0]
    assert "aux_pass_range = range(_AUX_PASSES)" in baseline_multigpu_worker
    assert "for _ in aux_pass_range:" in baseline_multigpu_worker
    assert "for _ in range(_AUX_PASSES):" not in baseline_multigpu_worker
    assert "self._aux_pass_range = range(_AUX_PASSES)" in baseline_multigpu_source
    assert "for _ in self._aux_pass_range:" in baseline_multigpu_benchmark
    assert "for _ in range(_AUX_PASSES):" not in baseline_multigpu_benchmark


