    base_model = VectorizedTopKMoE(hidden_size=8, num_experts=4, top_k=2, expansion=1)
    base_indices = base_model._flat_token_indices_for(3, torch.device("cpu"))
    base_ptr = base_indices.data_ptr()
    base_indices_again = base_model._flat_token_indices_for(3, torch.device("cpu"))
    assert base_indices_again.data_ptr() == base_ptr
    torch.testing.assert_close(
        base_indices_again,
        torch.tensor([0, 0, 1, 1, 2, 2], dtype=torch.int64),
    )
    base_values = torch.empty(6, 8)
    base_combine = base_model._combine_index_for(base_indices_again, base_values)
    base_combine_again = base_model._combine_index_for(base_indices_again, base_values)
    assert base_combine_again is base_combine
    assert base_combine.shape == (6, 8)
    torch.testing.assert_close(base_combine[:, 0], base_indices_again)
    x_base = torch.randn(3, 8)
    with torch.inference_mode():
        base_output = base_model(x_base)
        output_ptr = base_output.data_ptr()
        flat_tokens_ptr = base_model._flat_tokens_buffer.data_ptr()
        base_output_snapshot = base_output.clone()
        base_output_again = base_model(x_base)
        base_output_smaller = base_model(x_base[:2])
    assert base_output_again.data_ptr() == output_ptr
    assert base_output_smaller.shape == (2, 8)
    assert base_output_smaller.data_ptr() == output_ptr
    assert base_model._flat_tokens_buffer.data_ptr() == flat_tokens_ptr
    assert base_model._flat_tokens_buffer.numel() >= x_base.numel() * base_model.top_k
    assert base_model._scatter_output_buffer.numel() >= x_base.numel()
    torch.testing.assert_close(base_output_again, base_output_snapshot)

    model = GroupedTopKMoE(hidden_size=8, num_experts=4, top_k=2, expansion=1)
    model.capacity = 64
    model.configure_static_dispatch_buffers(batch_size=3, device=torch.device("cpu"))
    token_ptr = model._static_token_indices.data_ptr()
    expert_ptr = model._static_expert_range.data_ptr()
    overflow_ptr = model._static_overflow_slots.data_ptr()
    combine_ptr = model._static_combine_index.data_ptr()
    dense_ptr = model._static_dense_input.data_ptr()
    output_ptr = model._static_output_buffer.data_ptr()

    x = torch.randn(3, 8)
    with torch.inference_mode():
        expected = model(x).clone()
    flat_tokens_ptr = model._flat_tokens_buffer.data_ptr()
    model._static_output_buffer.fill_(float("nan"))
    model.assume_static_no_overflow = True
    with torch.inference_mode():
        output = model(x)

    assert output.shape == (3, 8)
    assert not torch.isnan(output).any()
    torch.testing.assert_close(output, expected)
    assert model._static_token_indices.data_ptr() == token_ptr
    assert model._static_expert_range.data_ptr() == expert_ptr
    assert model._static_overflow_slots.data_ptr() == overflow_ptr
    assert model._static_combine_index.data_ptr() == combine_ptr
    assert model._static_dense_input.data_ptr() == dense_ptr
    assert model._static_output_buffer.data_ptr() == output_ptr
    assert model._flat_tokens_buffer.data_ptr() == flat_tokens_ptr
    torch.testing.assert_close(
        model._static_token_indices,
        torch.tensor([0, 0, 1, 1, 2, 2], dtype=torch.int64),
    )
    assert model._static_expert_range.shape == (4, 1)
    assert model._static_overflow_slots.unique().item() == 4 * 64
    assert model._static_combine_index.shape == (6, 8)
    torch.testing.assert_close(model._static_combine_index[:, 0], model._static_token_indices)
    grouped_values = torch.empty(6, 8)
    assert model._combine_index_for(model._static_token_indices, grouped_values) is model._static_combine_index
    assert model._static_dense_input.shape == (4 * 64 + 1, 8)
    assert model._static_output_buffer.shape == (3, 8)

    fallback_model = GroupedTopKMoE(hidden_size=8, num_experts=4, top_k=2, expansion=1)
    fallback_indices = fallback_model._flat_token_indices_for(3, torch.device("cpu"))
    fallback_values = torch.empty(6, 8)
    fallback_combine = fallback_model._combine_index_for(fallback_indices, fallback_values)
    fallback_combine_again = fallback_model._combine_index_for(fallback_indices, fallback_values)
    assert fallback_combine_again is fallback_combine
    torch.testing.assert_close(fallback_combine[:, 0], fallback_indices)


