def test_moe_cuda_adaptive_router_keeps_training_path_differentiable() -> None:
    from labs.moe_cuda.optimized_router import AdaptiveTopKMoE

    torch.manual_seed(0)
    model = AdaptiveTopKMoE(hidden_size=4, num_experts=3, top_k=2)
