        bench._host_slot_count = 1
        cache_k = [torch.full((2, 1, 4), float(idx)) for idx in range(3)]
        cache_v = [torch.full((2, 1, 4), float(idx + 10)) for idx in range(3)]

        gathered_k, gathered_v = bench._gather_kv_into_buffers(
            cache_k,
            cache_v,
            ["local", "peer", "host"],
        )

        assert gathered_k.data_ptr() == bench._k_gather_buffer.data_ptr()
        assert gathered_v.data_ptr() == bench._v_gather_buffer.data_ptr()
        torch.testing.assert_close(gathered_k, torch.cat(cache_k, dim=1))
        torch.testing.assert_close(gathered_v, torch.cat(cache_v, dim=1))

        placed = bench._place_kv(cache_k[1], cache_v[1], step=1)
        placed_k, placed_v, tier = placed[:3]
        assert tier == "host"
        assert placed_k.data_ptr() == bench._host_key_slots[0].data_ptr()
        assert placed_v.data_ptr() == bench._host_value_slots[0].data_ptr()
        torch.testing.assert_close(placed_k, cache_k[1])
        torch.testing.assert_close(placed_v, cache_v[1])

        bench._k_gather_buffer.zero_()
        bench._v_gather_buffer.zero_()
        appended_k, appended_v = bench._append_kv_into_buffers(
            cache_k,
            cache_v,
            ["local", "peer", "host"],
            1,
        )

        assert appended_k.data_ptr() == bench._k_gather_buffer.data_ptr()
        assert appended_v.data_ptr() == bench._v_gather_buffer.data_ptr()
        torch.testing.assert_close(appended_k[:, :1, :], torch.zeros_like(cache_k[0]))
        torch.testing.assert_close(appended_k[:, 1:2, :], cache_k[1])
        torch.testing.assert_close(appended_v[:, :1, :], torch.zeros_like(cache_v[0]))
        torch.testing.assert_close(appended_v[:, 1:2, :], cache_v[1])


